"""Regenerate the water fixtures (W3; stdlib only, deterministic).

  Content/textures/water-ripples.png        a tiling ripple normal map (linear, blue up) from a
                                            few sine waves with whole cycles per tile
  Content/materials/water/lake.swmaterial   the lake: shallow, deep and foam values the GPU check
                                            measures against, ripples drifting at 0.3 m/s
  Content/materials/water/lake-flat.swmaterial  the same without its ripple map (nothing bends)
  Scenes/shading-water.swscene              a sand bottom sloping down under a 12 m water plane,
                                            a red post standing in it, a low sun
  Scenes/shading-water-flat.swscene         the same with lake-flat
  Scenes/shading-water-none.swscene         the same without the water
  Scenes/shading-water-builtin.swscene      the same with the built-in "water" material
Run it after changing it; the outputs are committed so tests don't need Python.
"""
import math, struct, zlib
from pathlib import Path

root = Path(__file__).resolve().parents[1]
HEADER = '# Generated by Tests/fixtures/graphics/Tools/water.py; edit that, not this file.\n'


def png(width, height, pixels):
    def chunk(kind, data):
        return struct.pack('>I', len(data)) + kind + data + struct.pack('>I', zlib.crc32(kind + data) & 0xffffffff)
    rows = b''.join(b'\0' + bytes(pixels[y * width * 4:(y + 1) * width * 4]) for y in range(height))
    return (b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', width, height, 8, 6, 0, 0, 0)) +
            chunk(b'IDAT', zlib.compress(rows, 9)) + chunk(b'IEND', b''))


def ripples(size=128):
    waves = [(1, 2, 0.30, 0.0), (3, -1, 0.22, 1.7), (-2, 3, 0.18, 4.1), (5, 2, 0.10, 2.3), (-4, -5, 0.07, 5.2)]
    tau = 2 * math.pi
    pixels = []
    for y in range(size):
        for x in range(size):
            u, v = (x + 0.5) / size, (y + 0.5) / size
            du = dv = 0.0
            for kx, ky, a, phase in waves:
                c = math.cos(tau * (kx * u + ky * v) + phase) * a * tau
                du += c * kx
                dv += c * ky
            n = (-du * 0.04, -dv * 0.04, 1.0)
            length = math.sqrt(sum(c * c for c in n))
            pixels += [round((c / length * 0.5 + 0.5) * 255) for c in n] + [255]
    return png(size, size, pixels)


(root / 'Content/textures/water-ripples.png').write_bytes(ripples())
materials = root / 'Content/materials/water'
materials.mkdir(parents=True, exist_ok=True)
(materials / 'lake.swmaterial').write_text(
    HEADER + 'swmaterial 1\nfamily water\nwater_shallow_color 0.1 0.6 0.5\nwater_deep_color 0.01 0.03 0.12\n'
    'water_depth_fade 1.5\nwater_clarity 1\ntexture water_normal "textures/water-ripples.png"\n'
    'water_ripple_scale 2\nwater_ripple_speed 0.3\nwater_foam_distance 0.15\n')
(materials / 'lake-flat.swmaterial').write_text(
    HEADER + 'swmaterial 1\nparent "materials/water/lake.swmaterial"\nclear_texture water_normal\n'
    'water_ripple_speed 0\n')


def scene(name, note, water):
    lines = [HEADER.rstrip()] + ['# ' + line for line in note] + [
        'shockwave_scene 2', '',
        'entity "Environment"', '  Environment', '    sky_color 0.45 0.55 0.7 1', '    ground_color 0.2 0.18 0.15 1',
        '    ambient_intensity 0.5', '    bloom_intensity 0', 'end', '',
        'entity "Sun"', '  Transform', '    rotation -40 25 0', '  Light', '    type Directional',
        '    color 1 0.96 0.9 1', '    intensity 3', 'end', '',
        # The bottom: sand sloping down 6 degrees away from the camera, crossing the
        # water's surface (y 0) at about z 3.
        'entity "Bottom"', '  Transform', '    position 0 -0.1 3', '    rotation -6 0 0', '    scale 14 0.2 20',
        '  MeshRenderer', '    mesh cube', '    tint 0.5 0.44 0.3 1', 'end', '',
        'entity "Post"', '  Transform', '    position 1.5 0 0.5', '    scale 0.15 2.4 0.15', '  MeshRenderer',
        '    mesh cube', '    tint 0.85 0.08 0.06 1', 'end', '']
    if water:
        material = water if water == 'water' else f'"materials/water/{water}.swmaterial"'
        lines += ['entity "Water"', '  Transform', '    scale 12 1 12', '  MeshRenderer', '    mesh plane',
                  f'    material {material}', '    cast_shadows false', 'end', '']
    lines += ['entity "Main Camera"', '  Transform', '    position 0 4 8', '    rotation -28 0 0', '  Camera',
              '    fov 60', '    near_plane 0.1', '    primary 1', 'end', '']
    (root / f'Scenes/{name}.swscene').write_text('\n'.join(lines))


scene('shading-water', ['Water (W3): sand sloping gently down under a lake, shallow near the shore, deep far off,',
                        'foam along the shoreline and a red post standing in it. Camera: "Main Camera".'], 'lake')
scene('shading-water-flat', ['shading-water.swscene with the lake\'s ripple map cleared: nothing bends.'], 'lake-flat')
scene('shading-water-none', ['shading-water.swscene without its water.'], None)
scene('shading-water-builtin', ['shading-water.swscene with the built-in "water" material.'], 'water')
